import{_ as l,o as i,c as e,ak as r,am as o,an as s,ao as p,ap as t,aq as n,ar as d}from"./chunks/framework.HyOigXlE.js";const P=JSON.parse('{"title":"串口调试环境配置","description":"","frontmatter":{},"headers":[],"relativePath":"docs/hardware/serial-port.md","filePath":"docs/hardware/serial-port.md","lastUpdated":1788320201000}'),h={name:"docs/hardware/serial-port.md"};function m(c,a,b,u,_,f){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="串口调试环境配置" tabindex="-1">串口调试环境配置 <a class="header-anchor" href="#串口调试环境配置" aria-label="Permalink to “串口调试环境配置”">​</a></h1><h2 id="modbus-模拟器" tabindex="-1">modbus 模拟器 <a class="header-anchor" href="#modbus-模拟器" aria-label="Permalink to “modbus 模拟器”">​</a></h2><h3 id="在-windows-上搭建模拟调试设备" tabindex="-1">在 windows 上搭建模拟调试设备 <a class="header-anchor" href="#在-windows-上搭建模拟调试设备" aria-label="Permalink to “在 windows 上搭建模拟调试设备”">​</a></h3><ul><li><p>硬件: windows 电脑、usb 转 232 线 2 根，公母各一根</p></li><li><p>软件：Modbus Slave</p></li></ul><h3 id="调试步骤" tabindex="-1">调试步骤 <a class="header-anchor" href="#调试步骤" aria-label="Permalink to “调试步骤”">​</a></h3><ol><li><p>连接两根 usb 转 232 线，分别接入到开发和模拟电脑</p></li><li><p>在模拟电脑安装 Modbus Slave</p></li><li><p>配置模拟数据</p><ol><li><p>打开 Modbus Slave 新建文件。</p><ol><li>可以新建多个数据文件(根据 Slave Definition 的 Function 类型)</li></ol></li><li><p>选中文件，点击上方 setup 按钮，点击 Slave Definition...,在弹出框设置：</p><ol><li><p>设置 Slave ID</p></li><li><p>选择 Function，比如要测试寄存器，Function 就选择【 03 Holding Register(4x) 】</p></li><li><p>点击确定保存</p></li></ol></li><li><p>点击 Connection-&amp;gt;connection...,在弹出框设置：</p><ol><li><p>Connection: 选择 SerialPort</p></li><li><p>Serial Settings: 选择设置串口配置，例如： 9600Baud、其他默认</p></li><li><p>点击确定保存</p></li><li><p>此时 红色未连接状态会消失，表示已经连接成功</p></li></ol></li><li><p>⚠️ 注意：如果连接失败，可以多次尝试如下操作</p><ol><li><p>先断开连接</p></li><li><p>选择比较低的波特率连接</p></li><li><p>成功后断开连接</p></li><li><p>再连接需要测试的波特率</p></li></ol></li></ol></li><li><p>开发端浏览器连接对应的 usb 串口，查看调试面板会有连接信息打印。</p></li></ol><h2 id="图文示例" tabindex="-1">图文示例 <a class="header-anchor" href="#图文示例" aria-label="Permalink to “图文示例”">​</a></h2><h3 id="modbus-slave" tabindex="-1">Modbus Slave <a class="header-anchor" href="#modbus-slave" aria-label="Permalink to “Modbus Slave”">​</a></h3><p><img src="'+o+'" alt="Image"><img src="'+s+'" alt="Image"><img src="'+p+'" alt="Image"></p><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to “浏览器”">​</a></h3><p><img src="'+t+'" alt="Image"><img src="'+n+'" alt="Image"><img src="'+d+'" alt="Image"></p><h2 id="实际开发注意事项" tabindex="-1">实际开发注意事项 <a class="header-anchor" href="#实际开发注意事项" aria-label="Permalink to “实际开发注意事项”">​</a></h2><h3 id="_1、配置注意事项" tabindex="-1">1、配置注意事项 <a class="header-anchor" href="#_1、配置注意事项" aria-label="Permalink to “1、配置注意事项”">​</a></h3><ul><li><p>连接时有可能找不到设备或者某些波特率无法获取数据，需要排查下电脑系统及使用的测试线</p><ul><li>测试使用的线是否正常，不同的线数据表现也不一致</li></ul></li><li><p>模拟端和开发端 modbus 配置要一致,尤其注意以下配置:</p><ul><li><p>baudRate【<em>波特率</em>】</p></li><li><p>parity【<em>校验位</em>】</p></li><li><p>dataBits【<em>数据位</em>】</p></li><li><p>stopBits【<em>停止位</em>】</p></li></ul></li></ul><h3 id="_2、开发注意项" tabindex="-1">2、开发注意项 <a class="header-anchor" href="#_2、开发注意项" aria-label="Permalink to “2、开发注意项”">​</a></h3><ul><li><p>使用 chrome 浏览器开发调试使用</p></li><li><p>开发环境使用 【 localhost 】，生产环境使用 【 https 】，其他 IP 及 http 等由于浏览器安全策略会禁止连接串口</p></li><li><p>每次更新后要刷新浏览器并重新连接串口</p></li><li><p>有时连接上了但是读取数据超时，可以尝试重新设置 Modbus Slave 连接，重新拔插 usb 线</p></li></ul>',16)])])}const S=l(h,[["render",m]]);export{P as __pageData,S as default};
